function [m] = rot1(a)
%ROT1  The elementary rotations about x, y and z by an angle [rad] (passive: R3(a) = [c s 0; -s c 0; 0 0 1]).
%   a: real[1] (passed a plain number)
%   returns m: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    m = zeros(3, 3);
    s = sin(a);
    c = cos(a);
    m = [([1; 0; 0]).'; ([0; c; s]).'; ([0; (-(s)); c]).'];
end
